import { prisma } from "../config/client";
import Groq from "groq-sdk";
// Initialize Groq SDK (Make sure GROQ_API_KEY is in your .env file)
const groq = new Groq({
    apiKey: process.env.API_KEY,
});
/**
 * Helper function to call Groq API and generate quiz questions JSON
 */
const generateQuizQuestions = async (topic, numberOfQuestions, questionType) => {
    const systemPrompt = `You are an expert quiz generator. Your task is to generate high-quality quiz questions in strict JSON format. Output JSON ONLY without markdown formatting or code blocks.`;
    const userPrompt = `
Generate ${numberOfQuestions} quiz questions on the topic "${topic}".
Requested Question Type: ${questionType} (MCQ, MULTI_CORRECT, or TRUE_FALSE).

Return a JSON object with a single key "questions" containing an array of question objects.
Required JSON format:
{
  "questions": [
    {
      "text": "Question statement here",
      "type": "${questionType}",
      "timeLimit": 20,
      "points": 1000,
      "options": [
        { "text": "Option 1", "isCorrect": true },
        { "text": "Option 2", "isCorrect": false },
        { "text": "Option 3", "isCorrect": false },
        { "text": "Option 4", "isCorrect": false }
      ]
    }
  ]
}

Rules:
1. For MCQ: Provide exactly 4 options with exactly 1 option having "isCorrect": true.
2. For TRUE_FALSE: Provide exactly 2 options ("True" and "False") with exactly 1 having "isCorrect": true.
3. For MULTI_CORRECT: Provide 4 options where 2 or more have "isCorrect": true.
`;
    const chatCompletion = await groq.chat.completions.create({
        messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt }
        ],
        model: "llama-3.3-70b-versatile",
        response_format: { type: "json_object" }, // Guarantees JSON response
        temperature: 0.7,
    });
    const content = chatCompletion.choices[0]?.message?.content;
    if (!content) {
        throw new Error("Failed to receive response from Groq API");
    }
    const parsedData = JSON.parse(content);
    return parsedData.questions || [];
};
/**
 * Controller to generate a Quiz by AI and save to DB
 */
const GenerateQuizByAI = async (req, res) => {
    try {
        const { topic, numberOfQuestions, questionType } = req.body;
        const userId = req.user?.id;
        if (!userId) {
            return res.status(401).json({ message: "Unauthorized" });
        }
        if (!topic || !numberOfQuestions) {
            return res.status(400).json({ message: "Topic and number of questions are required." });
        }
        // 1. Generate questions using Groq AI
        const questions = await generateQuizQuestions(topic, numberOfQuestions, questionType || "MCQ");
        if (!questions || questions.length === 0) {
            return res.status(500).json({ message: "Failed to generate questions." });
        }
        // 2. Save Quiz and nested Questions/Options in PostgreSQL via Prisma
        const newQuiz = await prisma.quiz.create({
            data: {
                title: `AI Quiz: ${topic}`,
                description: `Generated by AI on the topic of "${topic}"`,
                ownerId: userId,
                quizQuestions: {
                    create: questions.map((question, index) => ({
                        order: index + 1,
                        question: {
                            create: {
                                text: question.text,
                                type: question.type || "MCQ",
                                timeLimit: question.timeLimit || 20,
                                points: question.points || 1000,
                                creatorId: userId,
                                options: {
                                    create: question.options.map((option) => ({
                                        text: option.text,
                                        isCorrect: option.isCorrect,
                                    })),
                                },
                            },
                        },
                    })),
                },
            },
            include: {
                quizQuestions: {
                    include: {
                        question: {
                            include: {
                                options: true,
                            },
                        },
                    },
                },
            },
        });
        res.status(201).json(newQuiz);
    }
    catch (error) {
        console.error("Error generating AI quiz:", error);
        res.status(500).json({
            message: "Internal Server Error",
        });
    }
};
export { GenerateQuizByAI };
